import{_ as t,o as d,c as a,a2 as r}from"./chunks/framework.BetZR81g.js";const u=JSON.parse('{"title":"API 안내","description":"","frontmatter":{"lang":"ko","sourcePath":"docs/api.ko.md"},"headers":[],"relativePath":"ko/guide/api.md","filePath":"ko/guide/api.md"}'),o={name:"ko/guide/api.md"};function i(c,e,n,s,h,p){return d(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="api-안내" tabindex="-1">API 안내 <a class="header-anchor" href="#api-안내" aria-label="Permalink to &quot;API 안내&quot;">​</a></h1><blockquote><p>sfml.js는 SFML 3.1.0을 기반으로 합니다. 직접 작성한 가이드는 사용법, 반환값, Node.js에 맞춘 조정을 설명하며, 전체 시그니처와 타입 제약은 소스에서 생성한 <a href="/ko/reference/" target="_self">TypeDoc</a>에서 제공합니다.</p></blockquote><p><a href="/ko/guide/">문서 홈</a> · <a href="/ko/guide/getting-started">빠른 시작</a> · <a href="/ko/guide/concepts">핵심 개념</a></p><p>모든 공개 인터페이스는 <code>sfml.js</code>에서 가져옵니다. 내보내기 목록은 <a href="https://github.com/XadillaX/node-sfml/blob/main/src/index.ts" target="_blank" rel="noreferrer">src/index.ts</a>를 참고하세요. 애플리케이션 코드에서 <code>dist/internal</code>이나 네이티브 모듈 핸들에 접근할 필요는 없습니다.</p><h2 id="작업별-선택" tabindex="-1">작업별 선택 <a class="header-anchor" href="#작업별-선택" aria-label="Permalink to &quot;작업별 선택&quot;">​</a></h2><table tabindex="0"><thead><tr><th>작업</th><th>문서</th><th>주요 인터페이스</th></tr></thead><tbody><tr><td>좌표, 각도, 프레임 시간 계산</td><td><a href="/ko/guide/system">System</a></td><td>Vector2/3, Angle, Time, Clock, 이름 있는 연산자</td></tr><tr><td>사용자 정의 파일 소스 연결</td><td><a href="/ko/guide/system#input-streams">입력 스트림</a></td><td>InputStream, MemoryInputStream, FileInputStream</td></tr><tr><td>창 열기와 입력 수신</td><td><a href="/ko/guide/window">Window</a></td><td>RenderWindow, Window, Event, Keyboard, Mouse</td></tr><tr><td>이미지와 애니메이션 표시</td><td><a href="/ko/guide/graphics">Graphics</a></td><td>Image, Texture, Sprite</td></tr><tr><td>도형과 텍스트 그리기</td><td><a href="/ko/guide/graphics">Graphics</a></td><td>Shape, Font, Glyph, Text</td></tr><tr><td>카메라, 오프스크린 합성, 일괄 지오메트리 처리</td><td><a href="/ko/guide/graphics">Graphics</a></td><td>View, RenderTexture, VertexArray, VertexBuffer</td></tr><tr><td>사용자 정의 그리기와 셰이더</td><td><a href="/ko/guide/graphics">Graphics</a></td><td>Drawable, RenderStates, Shader, Glsl</td></tr><tr><td>재생, 녹음, 오디오 처리</td><td><a href="/ko/guide/audio">Audio</a></td><td>SoundBuffer, Sound, Music, SoundStream, SoundRecorder</td></tr><tr><td>네트워크 연결과 파일 전송</td><td><a href="/ko/guide/network">Network</a></td><td>Packet, TcpSocket, UdpSocket, Http, Ftp, Sftp</td></tr></tbody></table><h2 id="system" tabindex="-1">System <a class="header-anchor" href="#system" aria-label="Permalink to &quot;System&quot;">​</a></h2><p><code>Vector2</code>/<code>Vector3</code>는 여러 스칼라 타입을 지원합니다. <code>Vector2i/u/f</code>와 <code>Vector3i/u/f</code>는 자주 사용하는 특수화입니다. <code>degrees()</code>/<code>radians()</code>로 Angle을, 시간 팩토리 함수로 Time을 생성합니다.</p><p>JavaScript에는 C++ 연산자 오버로딩이 없으므로 해당 연산에는 <code>add()</code>, <code>multiply()</code>, <code>equal()</code>, <code>*Assign()</code>을 사용합니다. <code>Clock</code>, 비동기 <code>sleep()</code>, <code>TimeoutWithPredicate</code>, 입력 스트림, <code>Unicode</code>, 오류 로그 인터페이스도 이 모듈에 속합니다.</p><p>자세한 내용은 <a href="/ko/guide/system">System</a>을 참고하세요.</p><h2 id="window" tabindex="-1">Window <a class="header-anchor" href="#window" aria-label="Permalink to &quot;Window&quot;">​</a></h2><p><code>Window</code>는 시스템 창과 OpenGL 컨텍스트를 제공합니다. 2D 그리기에는 보통 Window와 RenderTarget의 기능을 함께 갖춘 <code>RenderWindow</code>를 사용합니다.</p><p>이벤트는 <code>pollEvent()</code>, <code>handleEvents()</code>, 동기식 <code>waitEvent()</code>로 가져올 수 있습니다. 키보드, 마우스, 조이스틱, 센서에는 실시간 조회 기능도 있습니다. <code>Clipboard</code>, <code>Cursor</code>, <code>Context</code>, <code>Vulkan</code>은 시스템 통합 기능을 담당합니다.</p><p>자세한 내용은 <a href="/ko/guide/window">Window</a>를 참고하세요.</p><h2 id="graphics" tabindex="-1">Graphics <a class="header-anchor" href="#graphics" aria-label="Permalink to &quot;Graphics&quot;">​</a></h2><p>Image는 CPU 측 픽셀을, Texture는 GPU 텍스처를 저장하며, Sprite는 텍스처를 참조해 그립니다. Shape는 원, 사각형, 볼록 다각형, 사용자 정의 볼록 도형을 제공합니다. Font와 Text는 폰트 로딩, 텍스트 레이아웃, 편집 가능한 정점을 제공합니다.</p><p>RenderTarget은 창과 오프스크린 대상의 그리기 인터페이스를 통일합니다. View는 카메라와 뷰포트를 제어하고, RenderStates는 변환, 블렌딩, 스텐실, 텍스처, Shader를 제어합니다. 정점 배열과 GPU 정점 버퍼로 지오메트리를 직접 구성할 수 있습니다.</p><p>자세한 내용은 <a href="/ko/guide/graphics">Graphics</a>와 <a href="/ko/guide/concepts#draw-snapshots">그리기 스냅샷</a>을 참고하세요.</p><h2 id="audio" tabindex="-1">Audio <a class="header-anchor" href="#audio" aria-label="Permalink to &quot;Audio&quot;">​</a></h2><p>짧은 효과음에는 SoundBuffer + Sound를, 긴 오디오에는 Music을 사용합니다. SoundSource는 볼륨, 패닝, 공간 오디오 속성을 제공합니다. SoundStream, SoundRecorder, EffectProcessor는 Worker 콜백으로 사용자 정의 데이터를 처리합니다.</p><p>자세한 내용은 <a href="/ko/guide/audio">Audio</a>를 참고하세요. 특히 샘플 수, 채널 배치, 버퍼의 유효 기간에 주의해야 합니다.</p><h2 id="network" tabindex="-1">Network <a class="header-anchor" href="#network" aria-label="Permalink to &quot;Network&quot;">​</a></h2><p>Network는 Node.js 전송 계층으로 SFML 스타일 API를 구현합니다. 실제 서비스 코드는 SFML C++ Network를 호출하지 않습니다. Packet은 SFML 인코딩 규칙을 유지하며, TCP, UDP, DNS, TLS, HTTP, FTP, SFTP의 I/O는 Promise를 사용합니다.</p><p>상태 반환, 부분 전송, 프로토콜 제한, 종료 방법을 포함한 자세한 내용은 <a href="/ko/guide/network">Network</a>를 참고하세요.</p><h2 id="호환-범위" tabindex="-1">호환 범위 <a class="header-anchor" href="#호환-범위" aria-label="Permalink to &quot;호환 범위&quot;">​</a></h2><table tabindex="0"><thead><tr><th>항목</th><th>현재 동작</th></tr></thead><tbody><tr><td>C++ 포인터, 참조 출력 매개변수</td><td>객체, 뷰, 반환 객체로 표현</td></tr><tr><td>C++ 템플릿 및 연산자</td><td>명시적인 스칼라 태그, 클래스, 이름 있는 함수로 표현</td></tr><tr><td>파일 로딩</td><td>Promise 사용, 구체적인 실패 상태는 각 인터페이스의 규칙을 유지</td></tr><tr><td>소멸</td><td>네이티브 소유권과 JS 참조를 함께 사용하며, 닫기 인터페이스가 있는 리소스는 명시적으로 닫아야 함</td></tr><tr><td><code>drawAsync()</code>/<code>displayAsync()</code></td><td>제공하지 않으며, 이전 예제에서 명시적으로 미지원으로 보고</td></tr><tr><td>Android SuspendAwareClock</td><td>조건부 컴파일 인터페이스가 있으며, 현재 다운로드 절차는 데스크톱 대상</td></tr><tr><td>Vulkan</td><td>조회 인터페이스가 내보내지며, 사용 가능 여부는 SFML 플랫폼 백엔드에 따라 결정됨. macOS 백엔드에서는 사용 불가</td></tr></tbody></table><p>플랫폼별 빌드와 테스트 범위는 <a href="/ko/guide/development#testing">개발 가이드</a>를 참고하세요.</p><p><a id="sfml-cpp-reference"></a></p><h2 id="sfml-c-레퍼런스" tabindex="-1">SFML C++ 레퍼런스 <a class="header-anchor" href="#sfml-c-레퍼런스" aria-label="Permalink to &quot;SFML C++ 레퍼런스&quot;">​</a></h2><p><a href="https://www.sfml-dev.org/documentation/3.1.0/" target="_blank" rel="noreferrer">SFML 3.1.0 공식 문서 색인</a>은 C++ API의 개념을 확인하는 기준입니다. JavaScript 시그니처와 타입 제약은 <a href="/ko/reference/" target="_self">TypeDoc</a>을 기준으로 하세요. 각 모듈의 관련 원본 클래스와 JS 차이는 아래에서 확인할 수 있습니다.</p><ul><li><a href="/ko/guide/system#sfml-cpp-reference">System C++ 레퍼런스</a></li><li><a href="/ko/guide/window#sfml-cpp-reference">Window C++ 레퍼런스</a></li><li><a href="/ko/guide/graphics#sfml-cpp-reference">Graphics C++ 레퍼런스</a></li><li><a href="/ko/guide/audio#sfml-cpp-reference">Audio C++ 레퍼런스</a></li><li><a href="/ko/guide/network#sfml-cpp-reference">Network C++ 레퍼런스</a></li></ul>',31)])])}const f=t(o,[["render",i]]);export{u as __pageData,f as default};
